// Jar dimensions: 40mm diameter, 120mm height

// Parameters
jar_diameter = 40;
jar_radius = jar_diameter / 2;
jar_height = 120;

// Stand parameters
wall_thickness = 2.5;
base_thickness = 3;
jar_spacing = 5; // Space between jars
holder_height = 35; // How much of the jar is held (enough to be secure but easy to remove)
step_height = 30; // Height difference between tiers (3cm)

// Grid parameters
grid_cols = 3;
grid_rows = 3;

// Calculated dimensions
cell_size = jar_diameter + wall_thickness;
total_width = grid_cols * cell_size + wall_thickness + (grid_cols - 1) * jar_spacing;
total_depth = grid_rows * cell_size + wall_thickness + (grid_rows - 1) * jar_spacing;
max_height = base_thickness + holder_height + (grid_rows - 1) * step_height;

// Module to create a single jar holder cavity
module jar_cavity(height) {
    // Slightly larger than jar for easy insertion/removal
    clearance = 0.5;
    cylinder(h = height + 1, r = jar_radius + clearance, $fn = 64);
}

// Module to create the tiered base
module tiered_base() {
    for (row = [0 : grid_rows - 1]) {
        tier_height = base_thickness + holder_height + row * step_height;
        row_y = row * (cell_size + jar_spacing);

        translate([0, row_y, 0])
            cube([total_width, cell_size + wall_thickness, tier_height]);
    }
}

// Module for the complete stand
module spice_stand() {
    difference() {
        // Create the tiered base
        tiered_base();

        // Cut out the jar holes
        for (row = [0 : grid_rows - 1]) {
            for (col = [0 : grid_cols - 1]) {
                // Calculate position for each jar
                x = wall_thickness + jar_radius + col * (cell_size + jar_spacing);
                y = wall_thickness + jar_radius + row * (cell_size + jar_spacing);
                tier_z = base_thickness + row * step_height;

                // Create the cylindrical cavity for the jar
                translate([x, y, tier_z])
                    jar_cavity(holder_height + step_height);
            }
        }

        // Add drainage/material saving holes in the base of each holder
        for (row = [0 : grid_rows - 1]) {
            for (col = [0 : grid_cols - 1]) {
                x = wall_thickness + jar_radius + col * (cell_size + jar_spacing);
                y = wall_thickness + jar_radius + row * (cell_size + jar_spacing);

                // Small drainage hole
                translate([x, y, -1])
                    cylinder(h = base_thickness + row * step_height + 2, r = jar_radius - 5, $fn = 64);
            }
        }
    }
}

// Render the stand
spice_stand();
