// Jar dimensions: 40mm diameter, 120mm height

// Parameters
jar_diameter = 40;
jar_radius = jar_diameter / 2;
jar_height = 120;

// Stand parameters
wall_thickness = 2.5;
base_thickness = 3;
jar_spacing = 6; // Space between jars
holder_height = 35; // How much of the jar is held (enough to be secure but easy to remove)
step_height = 30; // Height difference between tiers (3cm)

// Grid parameters
grid_cols = 3;
grid_rows = 3;

// Calculated dimensions
cell_outer = jar_diameter + wall_thickness * 2;
pitch_x = jar_diameter + wall_thickness + jar_spacing;
pitch_y = jar_diameter + wall_thickness + jar_spacing;
total_width = grid_cols * pitch_x + wall_thickness;
total_depth = grid_rows * pitch_y + wall_thickness;

// Clearance for jar insertion
jar_clearance = 0.5;

// Module to create a single jar holder
module jar_holder(tier) {
    tier_base_height = tier * step_height;
    total_holder_height = base_thickness + holder_height;

    difference() {
        // Outer cylinder for the holder
        cylinder(h = total_holder_height, r = jar_radius + wall_thickness + jar_clearance, $fn = 64);

        // Inner cavity for jar
        translate([0, 0, base_thickness])
            cylinder(h = total_holder_height + 1, r = jar_radius + jar_clearance, $fn = 64);

        // Drainage/material saving hole at bottom
        translate([0, 0, -1])
            cylinder(h = base_thickness + 2, r = jar_radius - 4, $fn = 64);
    }
}

// Module for a single tier platform
module tier_platform(tier) {
    tier_height = tier * step_height;
    y_start = tier * pitch_y;
    platform_depth = pitch_y + wall_thickness/2;

    // Platform base that connects the holders at this tier
    translate([0, y_start, 0])
        cube([total_width, platform_depth, tier_height + base_thickness]);
}

// Module for the complete stand
module spice_stand() {
    difference() {
        union() {
            // Create platforms for each tier
            for (tier = [0 : grid_rows - 1]) {
                tier_platform(tier);
            }

            // Create jar holders on each tier
            for (row = [0 : grid_rows - 1]) {
                for (col = [0 : grid_cols - 1]) {
                    x = wall_thickness + jar_radius + jar_clearance + col * pitch_x;
                    y = wall_thickness + jar_radius + jar_clearance + row * pitch_y;
                    z = row * step_height;

                    translate([x, y, z])
                        jar_holder(row);
                }
            }
        }

        // Cut drainage holes through the platforms
        for (row = [0 : grid_rows - 1]) {
            for (col = [0 : grid_cols - 1]) {
                x = wall_thickness + jar_radius + jar_clearance + col * pitch_x;
                y = wall_thickness + jar_radius + jar_clearance + row * pitch_y;

                translate([x, y, -1])
                    cylinder(h = row * step_height + base_thickness + 2, r = jar_radius - 4, $fn = 64);
            }
        }

        // Add finger notches for easier jar removal
        for (row = [0 : grid_rows - 1]) {
            for (col = [0 : grid_cols - 1]) {
                x = wall_thickness + jar_radius + jar_clearance + col * pitch_x;
                y = wall_thickness + jar_radius + jar_clearance + row * pitch_y;
                z = row * step_height + base_thickness;

                // Front notch
                translate([x, y - jar_radius - wall_thickness - 1, z + holder_height/2])
                    rotate([-90, 0, 0])
                        cylinder(h = wall_thickness + 2, r = 8, $fn = 32);
            }
        }
    }
}

// Render the stand
spice_stand();
