// Jar dimensions: 40mm diameter, 120mm height

// Parameters
jar_diameter = 40;
jar_radius = jar_diameter / 2;
jar_height = 120;

// Stand parameters
wall_thickness = 3;
base_thickness = 3;
jar_spacing = 5; // Space between jars
holder_height = 35; // How much of the jar is held (secure but easy to remove)
step_height = 30; // Height difference between tiers (3cm)

// Grid parameters
grid_cols = 3;
grid_rows = 3;

// Clearance for jar insertion
jar_clearance = 0.5;

// Calculated dimensions
holder_outer_radius = jar_radius + wall_thickness + jar_clearance;
pitch_x = holder_outer_radius * 2 + jar_spacing;
pitch_y = holder_outer_radius * 2 + jar_spacing;
total_width = grid_cols * pitch_x - jar_spacing + wall_thickness;
total_depth = grid_rows * pitch_y - jar_spacing + wall_thickness;
max_height = base_thickness + holder_height + (grid_rows - 1) * step_height;

// Module to create a single jar holder ring
module jar_holder_ring(height) {
    difference() {
        cylinder(h = height, r = holder_outer_radius, $fn = 64);
        translate([0, 0, -1])
            cylinder(h = height + 2, r = jar_radius + jar_clearance, $fn = 64);
    }
}

// Module for the complete stand
module spice_stand() {
    difference() {
        union() {
            // Create the tiered base structure
            for (row = [0 : grid_rows - 1]) {
                tier_height = base_thickness + row * step_height;
                y_start = row * pitch_y;

                // Platform for this row
                translate([0, y_start, 0])
                    cube([total_width, pitch_y, tier_height]);
            }

            // Add the jar holder cylinders rising from each platform
            for (row = [0 : grid_rows - 1]) {
                for (col = [0 : grid_cols - 1]) {
                    x = holder_outer_radius + col * pitch_x;
                    y = holder_outer_radius + row * pitch_y;
                    z = row * step_height;

                    translate([x, y, z])
                        cylinder(h = base_thickness + holder_height, r = holder_outer_radius, $fn = 64);
                }
            }
        }

        // Cut out the jar cavities
        for (row = [0 : grid_rows - 1]) {
            for (col = [0 : grid_cols - 1]) {
                x = holder_outer_radius + col * pitch_x;
                y = holder_outer_radius + row * pitch_y;
                z = row * step_height + base_thickness;

                // Main jar cavity
                translate([x, y, z])
                    cylinder(h = holder_height + 1, r = jar_radius + jar_clearance, $fn = 64);
            }
        }

        // Drainage holes through entire stack
        for (row = [0 : grid_rows - 1]) {
            for (col = [0 : grid_cols - 1]) {
                x = holder_outer_radius + col * pitch_x;
                y = holder_outer_radius + row * pitch_y;
                drain_height = row * step_height + base_thickness;

                translate([x, y, -1])
                    cylinder(h = drain_height + 2, r = jar_radius - 5, $fn = 64);
            }
        }

        // Finger notches on the front of each holder for easy removal
        for (row = [0 : grid_rows - 1]) {
            for (col = [0 : grid_cols - 1]) {
                x = holder_outer_radius + col * pitch_x;
                y = holder_outer_radius + row * pitch_y;
                z = row * step_height + base_thickness + holder_height * 0.6;

                // U-shaped notch on front
                translate([x, y - holder_outer_radius - 1, z])
                    rotate([-90, 0, 0])
                        cylinder(h = wall_thickness + 2, r = 10, $fn = 32);
            }
        }

        // Side cutouts to reduce material (optional, helps with printing)
        for (row = [1 : grid_rows - 1]) {
            tier_height = row * step_height;
            y_pos = row * pitch_y - jar_spacing/2;

            // Arch cutouts on left and right sides
            for (side = [0, 1]) {
                x_pos = side * total_width;
                translate([x_pos - 1, y_pos, 0])
                    rotate([0, 90, 0])
                        cylinder(h = wall_thickness + 2, r = min(tier_height - 3, 15), $fn = 32);
            }
        }
    }
}

// Render the stand
spice_stand();
